import pandas as pd
from scipy.stats import pearsonr

df = pd.read_csv('3901.csv')
corr_coef, p_value = pearsonr(df['TOTUSJH'], df['TOTUSJZ'])
corr_type = "No Significant Correlation"
if p_value < 0.05:
    if corr_coef > 0:
        corr_type = "Positive Correlation"
    elif corr_coef < 0:
        corr_type = "Negative Correlation"
    else:
        corr_type = "No Correlation"
print(f"@correlation_type[{corr_type}] @correlation_coefficient[{corr_coef:.2f}] @p_value[{p_value:.3f}]")

